const items = $input.all();

let jarvisCore = '';
const memories = [];

for (const item of items) {

  if (item.json.jarvis_core) {
    jarvisCore = item.json.jarvis_core;
  }

  if (item.json.memory_text) {
    memories.push(item.json.memory_text);
  }

}

return [
  {
    json: {
      jarvis_core: jarvisCore,
      memory_context: memories.join('\n')
    }
  }
];

const memories = $input.all().map(item => item.json);

// --------------------
// Профиль
// --------------------

const profile = {
  name: null,
  age: null,
  city: null,

  spouse: null,

  diabetes_type: null,
  diabetes_duration_years: null,

  hobbies: [],
  pets: []
};

// --------------------
// Вспомогательные функции
// --------------------

function getPet(index) {
  if (!profile.pets[index]) {
    profile.pets[index] = {};
  }

  return profile.pets[index];
}

// --------------------
// Разбор памяти
// --------------------

for (const memory of memories) {

  const key = memory.memory_key;
  const value = memory.memory_value;

  if (!key || value === null || value === undefined || value === "") {
    continue;
  }

  // ---------- Простые поля ----------

  switch (key) {

    case "name":
      profile.name = value;
      continue;

    case "age":
      profile.age = value;
      continue;

    case "city":
      profile.city = value;
      continue;

    case "spouse":
      profile.spouse = value;
      continue;

    case "diabetes_type":
      profile.diabetes_type = value;
      continue;

    case "diabetes_duration_years":
      profile.diabetes_duration_years = value;
      continue;
  }

  // ---------- Хобби ----------

  if (/^hobby(_\d+)?$/.test(key)) {
    profile.hobbies.push(value);
    continue;
  }

  // ---------- Питомцы ----------

  const petMatch = key.match(/^pet_(.+?)(?:_(\d+))?$/);

  if (petMatch) {

    const field = petMatch[1];

    const index = petMatch[2]
      ? Number(petMatch[2]) - 1
      : 0;

    const pet = getPet(index);

    pet[field] = value;

    continue;
  }

}

// --------------------
// Формирование ответа
// --------------------

const out = [];

out.push("Вот что я о тебе помню:");

if (profile.name) {
  out.push("");
  out.push(`👤 Имя: ${profile.name}`);
}

if (profile.age) {
  out.push(`🎂 Возраст: ${profile.age}`);
}

if (profile.city) {
  out.push(`🏙 Город: ${profile.city}`);
}

if (profile.spouse) {

  out.push("");
  out.push("❤️ Семья");
  out.push(`• Жена: ${profile.spouse}`);

}

if (profile.pets.length) {

  out.push("");
  out.push("🐱 Питомцы");

  for (const pet of profile.pets) {

    if (!pet) continue;

    out.push("");

    if (pet.type) {
      out.push(`• ${pet.type}`);
    }

    if (pet.name) {
      out.push(`  Имя: ${pet.name}`);
    }

    if (pet.color) {
      out.push(`  Цвет: ${pet.color}`);
    }

    // Автоматически покажет любые новые поля питомца

    for (const field of Object.keys(pet)) {

      if (["type", "name", "color"].includes(field)) {
        continue;
      }

      const label = field.replaceAll("_", " ");

      out.push(`  ${label}: ${pet[field]}`);

    }

  }

}

if (profile.diabetes_type || profile.diabetes_duration_years) {

  out.push("");
  out.push("🩺 Здоровье");

  if (profile.diabetes_type) {

    const map = {
      "1": "Диабет 1 типа",
      "2": "Диабет 2 типа"
    };

    out.push(`• ${map[profile.diabetes_type] ?? profile.diabetes_type}`);

  }

  if (profile.diabetes_duration_years) {
    out.push(`• Стаж: ${profile.diabetes_duration_years} лет`);
  }

}

if (profile.hobbies.length) {

  out.push("");
  out.push("🎸 Хобби");

  for (const hobby of profile.hobbies) {
    out.push(`• ${hobby}`);
  }

}

if (out.length === 1) {

  return [
    {
      json: {
        reply: "Пока я ничего о тебе не помню."
      }
    }
  ];

}

return [
  {
    json: {
      reply: out.join("\n")
    }
  }
];

options.systemMessage:
Ты анализируешь сообщение пользователя и определяешь, какие записи памяти необходимо удалить.

Верни ТОЛЬКО JSON.

Формат:

{
  "keys": [
    {
      "memory_key": "city"
    }
  ]
}

Правила:

1. Если пользователь просит забыть конкретный факт:
   "Забудь мой город"
   →
   {
     "keys":[
       {
         "memory_key":"city"
       }
     ]
   }

2. Если пользователь просит забыть несколько фактов:
   "Забудь как зовут жену и кота"
   →
   {
     "keys":[
       {
         "memory_key":"spouse"
       },
       {
         "memory_key":"pet_name"
       }
     ]
   }

3. Используй только существующие ключи памяти.

Допустимые ключи:

name
age
city

spouse

pet_name
pet_type
pet_color

diabetes_type
diabetes_duration_years

hobby
hobby_2
hobby_3

4. Если подходящего ключа нет, используй наиболее подходящий существующий.

5. Если пользователь просит забыть всё:
{
  "keys":[
    {
      "memory_key":"*"
    }
  ]
}

Никакого текста.
Только JSON.

