const items = $('Split Out1').all();

const labels = {
  "*": "всё, что знал о тебе",

  name: "имя",
  age: "возраст",
  city: "город",

  spouse: "имя жены",

  pet_name: "имя питомца",
  pet_type: "тип питомца",
  pet_color: "цвет питомца",

  diabetes_type: "диабет первого типа",
  diabetes_duration_years: "стаж диабета",

  hobby: "хобби",
  hobby_2: "второе хобби",
  hobby_3: "третье хобби"
};

const deleted = items.map(item => {
  const key = item.json.memory_key;
  return labels[key] ?? key;
});

let reply;

if (deleted.includes("всё, что знал о тебе")) {
  reply = "Хорошо. Я забыл всё, что знал о тебе.";
} else if (deleted.length === 1) {
  reply = `Хорошо. Я забыл ${deleted[0]}.`;
} else {
  reply = `Хорошо. Я забыл: ${deleted.join(", ")}.`;
}

return [
  {
    json: {
      reply
    }
  }
];

const labels = {
  name: "👤 Имя",
  age: "🎂 Возраст",
};

const lines = [];
const other = [];

for (const item of $input.all()) {
  const key = item.json.memory_key;
  const value = item.json.memory_value;

  // Пропускаем пустые записи
  if (!key || value === undefined || value === null || value === "") {
    continue;
  }

  if (labels[key]) {
    lines.push(`${labels[key]}: ${value}`);
  } else {
    other.push(`• ${key}: ${value}`);
  }
}

if (lines.length === 0 && other.length === 0) {
  return [
    {
      json: {
        reply: "Пока я ничего о тебе не помню.",
      },
    },
  ];
}

let text = "Вот что я о тебе помню:\n\n";

if (lines.length) {
  text += lines.join("\n");
}

if (other.length) {
  text += "\n\n📝 Остальное:\n";
  text += other.join("\n");
}
console.log(JSON.stringify(text));
return [
  {
    json: {
      reply: text,
    },
  },
];

const m = $("Prepare Memory").item.json;

return {
  user_id: $("Telegram Trigger").item.json.message.chat.id,
  category: m.category,
  memory_key: m.key,
  memory_value: m.value,
  memory_text: m.memory_text,
  embedding: JSON.stringify($json.data[0].embedding)
};

const unique = new Map();

for (const item of $input.all()) {
  const key = item.json.memory_key;

  if (!unique.has(key)) {
    unique.set(key, item);
  }
}

return Array.from(unique.values()).slice(0, 10);

const memories = $input.all();

const question = $('Telegram Trigger')
  .item.json.message.text
  .toLowerCase();

const result = [];

// Если пользователь просит показать всё
const showAllPatterns = [
  "что ты обо мне знаешь",
  "что ты помнишь",
  "покажи память",
  "моя память",
  "мой профиль"
];

const showAll = showAllPatterns.some(p => question.includes(p));

if (showAll) {
  return memories.slice(0, 10);
}

// Ключевые слова -> префиксы memory_key

const groups = [
  {
    words: ["кот", "кошка", "питом", "сема", "сёма"],
    prefixes: ["pet_"]
  },
  {
    words: ["диабет", "здоров"],
    prefixes: ["diabetes_"]
  },
  {
    words: ["хобби", "люблю", "увлека"],
    prefixes: ["hobby"]
  },
  {
    words: ["жена", "супруга", "семья"],
    prefixes: ["spouse"]
  },
  {
    words: ["город", "живу", "адрес"],
    prefixes: ["city"]
  },
  {
    words: ["возраст", "лет"],
    prefixes: ["age"]
  },
  {
    words: ["имя", "зовут"],
    prefixes: ["name"]
  }
];

let matchedPrefixes = [];

for (const group of groups) {
  if (group.words.some(w => question.includes(w))) {
    matchedPrefixes.push(...group.prefixes);
  }
}

if (matchedPrefixes.length === 0) {
  return memories.slice(0, 10);
}

for (const item of memories) {

  const key = item.json.memory_key;

  if (
    matchedPrefixes.some(prefix => key.startsWith(prefix))
  ) {
    result.push(item);
  }

}

return result.length
  ? result
  : memories.slice(0, 10);

